                if (!allDefault)
                {
                    w.U16(0x14fc); // fixed_bytes (fixed [17])
                    w.U8(14);
                    int lenAt = w.Len;
                    w.U32(0);
                    w.U8(6);
                    w.U16(17);
                    for (int i = 0; i < 17; i++)
                    {
                        w.U8((byte)value.FixedBytes[i]);
                    }
                    w.Patch32(lenAt, (uint)(w.Len - lenAt - 4));
                }
            }
            if (value.TextLength > 0)
            {
                w.U16(0xf3d8); // text
                w.U8(12);
                w.U16((ushort)value.TextLength);
                w.Raw(value.Text, value.TextLength);
            }
            w.U16(0); // terminator
        }

        // TableReadTestData decodes a table-wire buffer under the permissive contract:
        // declared defaults prefill, known fields overlay, unknown ids and kind
        // mismatches skip and count, out-of-range values clamp and count. false
        // means malformed — the partial decode up to that point is kept.
        public static bool TableReadTestData(byte[] data, ref TestData value, TableReport report)
        {
            TableReader r = new TableReader(data, 0, data.Length, report);
            return TableReadTestData(r, ref value);
        }

        private static bool TableReadTestData(TableReader r, ref TestData value)
        {
            value = new TestData(); // prefill declared defaults, then overlay
            while (true)
            {
                if (!r.Has(2))
                {
                    r.Report.Malformed = true;
                    return false;
                }
                ushort fieldId = r.Get16();
                if (fieldId == 0)
                {
                    return true;
                }
                if (!r.Has(1))
                {
                    r.Report.Malformed = true;
                    return false;
