                {
                    case 0xcd20: // a
                    {
                        if (kind != 4)
                        {
                            r.Report.KindMismatch++;
                            if (!r.Skip(kind))
                            {
                                r.Report.Malformed = true;
                                return false;
                            }
                            break;
                        }
                        if (!r.Has(4))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        int decoded = (int)r.Get32();
                        if (decoded < -100)
                        {
                            decoded = -100;
                            r.Report.Clamped++;
                        }
                        else if (decoded > 100)
                        {
                            decoded = 100;
                            r.Report.Clamped++;
                        }
                        value.A = (int)decoded;
                        break;
                    }
                    case 0xcae9: // b
                    {
                        if (kind != 4)
                        {
                            r.Report.KindMismatch++;
                            if (!r.Skip(kind))
                            {
                                r.Report.Malformed = true;
                                return false;
                            }
                            break;
                        }
                        if (!r.Has(4))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        int decoded = (int)r.Get32();
                        if (decoded < -100)
                        {
                            decoded = -100;
                            r.Report.Clamped++;
                        }
                        else if (decoded > 100)
                        {
                            decoded = 100;
                            r.Report.Clamped++;
                        }
                        value.B = (int)decoded;
                        break;
                    }
                    case 0xca5e: // c
                    {
                        if (kind != 4)
                        {
                            r.Report.KindMismatch++;
                            if (!r.Skip(kind))
                            {
                                r.Report.Malformed = true;
                                return false;
                            }
                            break;
                        }
                        if (!r.Has(4))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        int decoded = (int)r.Get32();
                        if (decoded < -100)
                        {
                            decoded = -100;
                            r.Report.Clamped++;
