                        value.C = (int)decoded;
                        break;
                    }
                    case 0xc57f: // d
                    {
                        if (kind != 6)
                        {
                            r.Report.KindMismatch++;
                            if (!r.Skip(kind))
                            {
                                r.Report.Malformed = true;
                                return false;
                            }
                            break;
                        }
                        if (!r.Has(1))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        byte decoded = r.Get8();
                        value.D = (uint)decoded;
                        break;
                    }
                    case 0xc2ec: // e
                    {
                        if (kind != 6)
                        {
                            r.Report.KindMismatch++;
                            if (!r.Skip(kind))
