                                return false;
                            }
                            break;
                        }
                        if (!r.Has(8))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        value.DoubleValue = r.GetF64();
                        break;
                    }
                    case 0x6592: // int8_value
                    {
                        if (kind != 2)
                        {
                            r.Report.KindMismatch++;
                            if (!r.Skip(kind))
                            {
                                r.Report.Malformed = true;
                                return false;
                            }
                            break;
                        }
                        if (!r.Has(1))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        sbyte decoded = (sbyte)r.Get8();
